#if !defined(ALL_YOUR_BASE_H)
#define ALL_YOUR_BASE_H

#include <vector>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int from_base,
                                  const std::vector<unsigned int>& in_digits,
                                  unsigned int to_base);

}  // namespace all_your_base

#endif // ALL_YOUR_BASE_H
EOF
cat > all_your_base.cpp <<'EOF'
#include "all_your_base.h"

#include <algorithm>
#include <cstdint>
#include <stdexcept>

namespace all_your_base {
namespace {

using Digit = unsigned int;
using Wide = std::uint64_t;

void validate_base(unsigned int base) {
    if (base < 2) {
        throw std::invalid_argument("base must be at least 2");
    }
}

}  // namespace

std::vector<Digit> convert(unsigned int from_base,
                           const std::vector<Digit>& in_digits,
                           unsigned int to_base) {
    validate_base(from_base);
    validate_base(to_base);

    const Wide source_base = static_cast<Wide>(from_base);
    const Wide target_base = static_cast<Wide>(to_base);

    // Digits are stored least-significant first during conversion.
    std::vector<Digit> out_digits;
    for (Digit digit : in_digits) {
        if (digit >= from_base) {
            throw std::invalid_argument("digit is not valid in the source base");
        }

        Wide carry = static_cast<Wide>(digit);
        for (Digit& out_digit : out_digits) {
            const Wide value = static_cast<Wide>(out_digit) * source_base + carry;
            out_digit = static_cast<Digit>(value % target_base);
            carry = value / target_base;
        }

        while (carry > 0) {
            out_digits.push_back(static_cast<Digit>(carry % target_base));
            carry /= target_base;
        }
    }

    std::reverse(out_digits.begin(), out_digits.end());
    return out_digits;
}

}  // namespace all_your_base
EOF
printf '%s\n' '--- header ---' && cat all_your_base.h && printf '%s\n' '--- source ---' && cat all_your_base.cpp", "note": "Create the initial implementation and expose the required conversion API in the header."}

