        if (leading_zero && digit == 0) {
            continue;
        }
        leading_zero = false;
        dividend.push_back(digit);
    }

    std::vector<unsigned int> result;
    while (!dividend.empty()) {
        std::vector<unsigned int> quotient;
        quotient.reserve(dividend.size());

        std::uint64_t remainder = 0;
