    while (i < v.size() && v[i] == 0) ++i;
    return vector<U>(v.begin() + i, v.end());
}

void check(U from, const vector<U>& in, U to, const vector<U>& expected) {
    auto got = all_your_base::convert(from, in, to);
    if (got != expected) {
        cerr << "MISMATCH " << from << " -> " << to << ": got";
        for (auto d : got) cerr << ' ' << d;
        cerr << " expected";
        for (auto d : expected) cerr << ' ' << d;
        cerr << '\n';
    }
    assert(got == expected);
}

void must_throw(U from, const vector<U>& in, U to) {
    bool ok = false;
    try { all_your_base::convert(from, in, to); }
    catch (const invalid_argument&) { ok = true; }
    assert(ok);
}

int main() {
    check(2, {0,0,1,0,1}, 10, {5});
    check(10, {0,0,4,2}, 2, {1,0,1,0,1,0});
