        U from = 2 + rng() % 63;
        U to = 2 + rng() % 63;
        size_t n = 1 + rng() % 8;
        vector<U> in;
        for (size_t i = 0; i < n; ++i) in.push_back(rng() % from);
        auto mid = all_your_base::convert(from, in, to);
        auto back = all_your_base::convert(to, mid, from);
        if (back != norm(in)) {
            cerr << "ROUNDTRIP FAIL at " << t << '\n';
